         ("/// <summary>Whether the die is set aside", "<code>Held</code> property, same pattern."),
         ("/// <summary>Whether another roll is available", "<code>ShowRollCaption</code>: when true, non-held dice show \"WILL ROLL\"."),
         ("protected override void OnEnabledChanged", "When enabled/disabled, switch the cursor and repaint (disabled dice look slightly faded)."),
         ("protected override void OnGotFocus", "Repaint when focus arrives or leaves, to draw or remove the focus rectangle."),
         ("/// <summary>Space or Enter", "Keyboard accessibility: Space/Enter on a focused die acts like a click."),
         ("protected override void OnPaint", "The painting routine. Anti-aliasing smooths the rounded corners and pips."),
         ("int captionHeight", "Layout: caption height converted to device pixels for the current DPI; the face is the largest square that fits above it, centred."),
         ("DrawFace(g, faceRect);", "Draws the face, then the caption beneath it."),
         ("private void DrawFace(", "Builds a rounded-rectangle outline (corner radius = 1/6 of the width). <code>using var</code> disposes the GDI object automatically."),
         ("Color face = _held", "Gold when held, white otherwise; slightly lightened when the control is disabled."),
         ("using (var fill", "Fills the shape and draws a thicker border for held dice."),
         ("if (Focused)", "Dotted focus rectangle for keyboard users."),
         ("if (_value == 0)", "Before the first roll the die shows a grey \"?\" and nothing else."),
         ("float cell = rect.Width / 4f;", "Pip geometry: the 3×3 grid points sit at ¼, ½ and ¾ of the face; pip radius is 1/11 of the width."),
         ("foreach (var (col, row) in PipLayout[_value])", "Looks up the pip positions for this face (tuple deconstruction) and draws a filled circle at each."),
         ("private void DrawCaption(", "Draws the caption under the die."),
